using System.Collections.Generic;

namespace AncientWarfare3.content.figures
{
    internal static class HistoricalFigureCardBiographiesFiveSong
    {
        public static void AddTo(IDictionary<string, string> pEntries)
        {
            pEntries.Add("duan_siping",
                "段思平（白语：Duainb Six-pienp，893年—944年），大理国的开国皇帝，937年至944年在位，谥圣神文武皇帝，庙号太祖。段思平生于太和城（今云南大理），其家族世代为南诏武将，父为南诏布燮段保隆，母为白姐阿妹（又作「阿垣」）。段思平因为累积军功而升任为大义宁通海节度使。杨干贞夺赵善政之位，干贞之弟杨诏谮思平有帝王之相，干贞于是追杀思平。");
            pEntries.Add("gao_jixing",
                "楚武信王高季兴（858年—929年），原名高季昌，因避后唐庄宗李存勖祖父李国昌的名讳，改为季兴，字贻孙，陕州硖石县（今河南三门峡市陕州区东南）人，五代十国时期荆南建立者（南平王、秦王），以江陵一城周旋于中原、诸侯之间，长于纵横之术。高季兴幼年为汴州商人李七郎（李七郎后为朱全忠义子，改名朱友让）家奴，后为朱友让收为义子，改姓为朱，由此得入军门，为朱全忠亲随牙将，因破凤翔救唐昭宗有功，被唐昭宗授“迎銮毅勇功臣”之号，迁宋州刺史。又随朱全忠扫荡青州，累功升颍州防御使，并复姓高氏。");
            pEntries.Add("jin_aizong",
                "金哀宗完颜守绪（1198年9月25日—1234年2月9日），金朝第九位皇帝（1224年1月15日－1234年2月9日在位），女真名宁甲速。金哀宗在位10年，直到1234年蒙宋联军即将攻破国都之际，其不欲做亡国之君、并将帝位传予金末帝完颜承麟，国破后自缢而死，终年35岁。哀宗生于金承安三年八月二十三日（1198年9月25日），初名守礼，是金宣宗第三子，母明惠皇后王氏。宣宗登位后，封守礼为遂王。");
            pEntries.Add("jin_hailing",
                "完颜亮（1122年2月24日—1161年12月15日），字元功，女真名迪古乃，金朝第四任皇帝（1150年1月9日－1161年12月15日在位）。金太祖完颜阿骨打之孙，太祖庶长子完颜宗干次子，母亲为大氏。金熙宗朝，完颜亮官至右丞相兼都元帅、太保领三省事，位极人臣。皇统九年末（1150年），完颜亮刺杀堂兄熙宗，即位改元。");
            pEntries.Add("jin_modi",
                "金末帝完颜承麟（1202年—1234年2月9日），金朝末代皇帝，金世祖完颜劾里鉢的后裔，原为金朝将领，蔡州城破前夕，不欲做亡国之君的金哀宗将帝位传予他，第二天即位大典完成时蒙宋联军已攻入城内，完颜承麟立刻率军迎敌，最后死于乱军之中。为东亚历史上在位最短的皇帝，史称金末帝、金后主。完颜承麟为金世祖完颜劾里鉢的后裔，哥哥完颜承裔为金朝将领，天兴二年（1233年）获罪死于狱中，完颜承麟受牵连被发配徐州安置。同年金哀宗为蒙古所迫，放弃汴京出逃，完颜承麟随徐州守将完颜仲德的军队护送哀宗至蔡州，被委任为都尉，天兴二年九月初九日（1233年10月13日）被任命为东面元帅孛术鲁娄室的副手。");
            pEntries.Add("jin_shizong",
                "金世宗完颜雍（1123年3月29日—1189年1月20日，天辅七年三月初一甲寅日－大定二十九年正月初二癸巳日），原名完颜褎（xiù），字彦举，女真名乌禄，又写作忽辣马、忽剌马、呼喇美，金朝第五位皇帝（1161年10月27日—1189年1月20日在位）。金太祖完颜阿骨打孙，在金朝时任皇帝完颜亮征宋时为辽东留守，不久后自立为帝，在位28年，终年67岁，葬于兴陵（今北京市房山区）。金世宗完颜雍（，天辅七年三月初一甲寅日－大定二十九年正月初二癸巳日），原名完颜，字彦举，女真名乌禄，又写作忽辣马、忽剌马、呼喇美，金朝第五位皇帝（1161年10月27日—1189年1月20日在位）。");
            pEntries.Add("jin_taizong",
                "完颜吴乞买继兄长完颜阿骨打即位，是金朝第二位皇帝，汉名完颜晟。他继续对辽作战并俘获辽天祚帝，随后大举南下，在靖康之变中攻破开封、俘虏宋徽宗和宋钦宗。其在位时期金朝由女真联盟转为统治华北的王朝，宋金长期对峙也由此形成。");
            pEntries.Add("jin_taizu",
                "完颜阿骨打（1068年8月1日—1123年9月19日），汉名完颜旻，金朝开国皇帝（1115年1月28日—1123年9月19日在位）。按出虎水（今黑龙江省哈尔滨东南阿什河）女真族完颜部酋长乌骨乃之孙，劾里鉢之次子，完颜部首领，在位9年，终年56岁。祖父是女真完顔部的族长乌古廼（景祖）、父劾里鉢是乌古廼的次子。生母是女真挐懒部首长的女儿翼简皇后。");
            pEntries.Add("jin_weishao",
                "完颜永济（？—1213年9月11日），小字兴胜，原名完颜允济，金章宗时避章宗父完颜允恭讳改名为完颜永济。他是金朝第七位皇帝（1208年12月29日—1213年9月11日在位），在位5年。在其被推翻身故后先降封为东海郡侯、再追复为卫王，卒谥「绍」。");
            pEntries.Add("jin_xizong",
                "金熙宗完颜亶（1119年8月14日—1150年1月9日），金朝第三位皇帝（1135年2月10日—1150年1月9日在位）。女真名合剌，汉名亶，是金太祖完颜阿骨打之嫡长孙，父为太祖嫡长子完颜宗峻、母为蒲察氏。生于天辅三年七月七日（1119年8月14日），卒于皇统九年十二月九日（1150年1月9日）。");
            pEntries.Add("jin_xuanzong",
                "金宣宗完颜珣（1163年4月18日—1224年1月14日），女真名吾睹补。金世宗完颜雍长孙，金章宗兄，卫绍王侄，父完颜允恭，母昭华刘氏。他是金朝第八位皇帝（1213年9月22日—1224年1月14日在位），在位11年，终年61岁。");
            pEntries.Add("jin_zhangzong",
                "金章宗完颜璟（1168年8月31日（农历七月二十七）—1208年12月29日），女真名麻达葛，金朝第6位皇帝（1189年1月20日—1208年12月29日在位），在位20年，享年41岁。章宗为金世宗完颜雍之嫡孙，其在位期间修订国内律法，政治清明，史称明昌之治。章宗统治下的金朝文化发展达至顶峰，但同时军事能力却也日益低下，蒙古帝国也于同时崛起。南宋主战派权臣韩侂胄于章宗年间北伐，但遭到金军击败，签定「嘉定和议」。");
            pEntries.Add("later_han_gaozu",
                "后汉高祖刘知远（895年3月4日—948年3月10日），并州晋阳（今山西太原）人，五代时期后汉开国皇帝，沙陀族，即位后改名为刘暠，947年－948年在位，谥号为睿文圣武昭肃孝皇帝。值得注意的是，刘知远大概并非刘邦之后，却在宗法上试图攀附两汉皇室。刘知远自称为东汉明帝第八子淮阳王刘昞之后，但被后世指为沙陀人，刘知远在太原出生，父亲刘琠为李克用麾下的小军官（列校）。刘知远最初是李嗣源（后来的后唐明宗）的部下，邺城之变，李嗣源登基后，刘知远在石敬瑭帐下任牙门都校。");
            pEntries.Add("later_han_yindi",
                "后汉隐帝刘承佑（931年3月28日—951年1月2日），并州晋阳（今山西太原）人，沙陀族，后汉第二个皇帝，948年－951年在位。初从父镇太原，署节院使，迁至检校尚书右仆射。后汉初年，授左卫大将军、检校司空，升任为大内都点检、检校太保。汉高祖乾佑元年（948年）正月，刘知远死后，秘不发丧。");
            pEntries.Add("later_jin_chudi",
                "晋出帝石重贵（914年—974年），942年－946年在位。天福七年（942年），后晋高祖石敬瑭死，重贵继位，沿用高祖天福年号，天福九年（944年）七月改元开运。石重贵不肯向契丹称臣，契丹攻后晋，开运三年十二月十七（947年1月11日）占开封，石重贵投降，后晋亡，史称晋出帝、晋少帝。");
            pEntries.Add("later_jin_gaozu",
                "晋高祖石敬瑭（892年3月30日—942年7月28日），五代十国时期的后晋开国皇帝（在位：936年11月28日－942年7月28日）。庙号高祖，谥号圣文章武明德孝皇帝。他把燕云十六州割让给契丹，使中原地区丧失了北方屏障，后代历朝亦认为难以抵御北方游牧民族系肇因于此，直至明朝初年才夺回对该地区的长期控制权。此外，石敬瑭为感谢契丹出手相助，就对契丹王朝俯首称臣。");
            pEntries.Add("later_liang_modi",
                "梁末帝朱友贞（888年10月24日—923年11月18日），后改名朱瑱、朱鍠，五代时期后梁皇帝，为后梁太祖朱温的嫡子，母张夫人。913年发动政变推翻弑父篡位的异母兄朱友珪后即位，在位期间信任赵岩、张汉杰等小人，在梁晋争霸中屡次失利丧失河北地区，最后在唐军攻入汴梁前自杀，亡国后被后唐追废为庶人，史称梁末帝、梁均王、梁少帝。朱友贞在位10年，在五代诸帝中在位年期最长。");
            pEntries.Add("later_liang_taizu",
                "梁太祖朱温（852年12月5日—912年7月18日），宋州砀山（今安徽省砀山县）人，五代时期后梁开国皇帝。本名朱温（小名朱三），唐僖宗赐名朱全忠，称帝后改名朱晃。唐末先从黄巢起事，后降唐，任节度使。907年废唐哀帝自立，建国号“梁”（史称后梁），为五代十国之始。");
            pEntries.Add("later_liang_yingwang",
                "朱友珪（885年—913年3月27日），五代时期后梁皇帝，为后梁太祖朱温之第三子，封郢王，912年朱温病重时弑父自立，次年为异母弟朱友贞发动政变推翻自杀。光启元年（885年）正月，刚刚上任宣武军节度使的朱温率军进驻亳州抵御秦宗权，召一营妓侍寝，一个月后将返回汴州，营妓却怀了孕。惧内的朱温就在亳州将她安顿了下来，最后生下了朱友珪，朱温很高兴，给他取小名“遥喜”，后来将他们接回汴州。开平元年（907年）朱温篡唐后，于五月初九（6月22日）将他封为郢王。");
            pEntries.Add("later_tang_mindi",
                "唐闵帝李从厚（914年—934年4月），小字菩萨奴，五代时期后唐皇帝，为后唐明宗李嗣源第三子，母昭懿皇后夏氏，有一胞兄李从荣。李嗣源因李从厚与自己相像，特别喜欢他。李从厚生于晋阳旧第，于李嗣源即位时，天成元年（926年），被任命为金紫光禄大夫，检校司徒。天成二年（927年），加检校太保、同平章事、河南尹，判六军诸卫事。");
            pEntries.Add("later_tang_mingzong",
                "唐明宗李亶（867年10月10日—933年12月15日），初名嗣源，小名邈佶烈，应州金城县（今山西省应县）人，沙陀族，五代十国时期后唐第二位皇帝（926年6月3日－933年12月15日在位），在位八年。唐河东节度使李克用之养子，生父为汾州刺史李霓。李嗣源本代北胡人，十二岁丧父。邈佶烈初以骑射为河东节度使李克用效命，从李克用征战，李克用则以李嗣源为养子，宠爱有加，从李姓，改名嗣源。");
            pEntries.Add("later_tang_modi",
                "唐末帝李从珂（885年2月11日—937年1月11日），镇州（今河北正定）人，五代时期后唐末代皇帝，本姓王，小字二十三，因此又称阿三。李从珂生于平山，十余岁时，其母魏氏被当时仍是将领的后唐明宗李嗣源所掳，李从珂不久就被李嗣源改名并收为养子。长大后身形雄伟健壮，又骁勇善战，常随李嗣源南征北讨，颇得其喜爱。庄宗也曾赞道：“阿三不惟与我同齿，敢战亦相类。");
            pEntries.Add("later_tang_zhuangzong",
                "唐庄宗李存勖（xù）（885年12月2日—926年5月15日），山西应县人，沙陀族，本姓朱邪，因其父是河东节度使李克用受唐懿宗赐姓而改姓李，讳存勖，亦作存勖（xù），唐光启元年正月（885年12月）生于山西应县（一说晋阳宫），五代时期后唐开国皇帝。小名“亚子”，艺名“李天下”，以勇猛闻名。923年5月13日在魏州（河北大名府）称帝，国号唐，史称后唐。后因义兄李嗣源被军士拥戴造反，挥军直取洛阳。");
            pEntries.Add("later_zhou_gongdi",
                "周恭帝郭宗训（953年9月14日—973年4月6日），五代时期后周皇帝，周世宗郭荣第四子。显德六年（959年）封为梁王。周世宗于同年六月驾崩，他于同月甲午日继位，沿用周世宗年号“显德”。");
            pEntries.Add("later_zhou_shizong",
                "后周世宗郭荣（921年10月27日—959年7月27日），本姓柴，故也习称柴荣，是五代时期后周第二位皇帝，于954年2月26日－959年7月27日在位，在位6年，庙号世宗，谥号睿武孝文皇帝。他是邢州尧山柴家庄（今河北省邢台市隆尧县）人，为周太祖郭威的内侄和养子，在郭威之后继承帝位。周世宗在位期间，在政治、军事、经济上都有建树，号称英主。");
            pEntries.Add("later_zhou_taizu",
                "周太祖郭威（904年9月10日—954年2月21日），字文仲，小名“郭雀儿”，籍贯邢州尧山（今河北隆尧）。五代时期后周开国皇帝（951年—954年）。原为后汉枢密使，却因隐帝疑忌，全家被杀。怒而起兵，隐帝死于乱军之中，郭威不久发动黄旗加身的兵变，建立后周。");
            pEntries.Add("li_maozhen",
                "秦忠敬王李茂贞（856年—924年），字正臣。深州博野（今河北蠡县）人。原名宋文通，曾为宦官田令孜螟蛉子，改名田彦宾。后受唐朝天子赐李姓，改名李茂贞，唐末军阀之一，五代时期岐国君主。");
            pEntries.Add("liao_daozong",
                "耶律洪基即辽道宗，在位四十余年，前期平定皇叔耶律重元发动的滦河之乱。他崇信佛教并大量营建寺塔，晚年却宠信耶律乙辛，导致皇后萧观音被诬杀、太子耶律濬遭害。乙辛集团败亡后道宗立皇孙耶律延禧为继承人，但辽朝政治与军事实力已经明显衰退。");
            pEntries.Add("liao_jingzong",
                "辽景宗耶律贤（948年9月1日—982年10月13日），字贤宁，辽朝第五位皇帝（969年3月13日－982年10月13日在位），在位13年，辽世宗的次子，其母为怀节皇后萧氏（《契丹国志》作甄皇后）。在辽世宗在位时的政变中，耶律贤险而被杀，后来得人所救。951年，其父辽世宗被刺身亡，堂叔耶律璟即位，是为辽穆宗。969年3月12日，堂叔辽穆宗被弑，次日，耶律贤被推举为帝，尊号天赞皇帝，改元为保宁。");
            pEntries.Add("liao_muzong",
                "辽穆宗耶律璟（931年9月19日—969年3月12日），一说名耶律明，小字述律，辽朝第四位皇帝（951年10月11日－969年3月12日在位），在位18年，是为辽太宗之长子，其母为靖安皇后萧温。于会同二年（939年）三月被封为寿安王。于天禄五年九月初八日（951年10月11日）火神淀之乱后，被立为帝，尊称天顺皇帝，改年号应历。应历二年（952年）六月，国舅政事令萧眉古得、宣政殿学士李澣谋划南奔，事发，穆宗下诏暴其罪。");
            pEntries.Add("liao_shengzong",
                "辽圣宗耶律隆绪（972年1月16日—1031年6月25日），辽朝第六位皇帝（982年10月14日—1031年6月25日在位），契丹名文殊奴。是辽国在位最长的皇帝，在位49年。辽景宗嫡长子，母圣神宣献皇后萧绰。");
            pEntries.Add("liao_shizong",
                "辽世宗耶律阮（919年1月29日—951年10月7日），中国辽朝第三位皇帝（947年5月16日－951年10月7日在位），在位4年。契丹迭剌部霞濑益石烈乡耶律里（今中国内蒙古阿鲁科尔沁旗东）人，姓耶律，汉文名阮，契丹文名兀欲（又名隈欲、乌云），他是大契丹国（后改称大辽国）皇太子、人皇王、东丹国王、辽义宗文献皇帝（追尊，未即位）耶律倍的长子、太祖耶律阿保机的长孙、太宗耶律德光之侄。阿保机死后，世宗耶律阮之父人皇王耶律倍在权力斗争中失利，未能即位为帝，耶律阮遂失去继承皇位的权利。");
            pEntries.Add("liao_taizong",
                "辽太宗耶律德光（902年11月25日—947年5月15日），大契丹国第二位皇帝（927年12月11日至947年5月15日在位），在位20年。字德谨，契丹名尧骨，《新五代史》写作「耀屈之」、《五代会要》写作「曜屈之」，辽太祖耶律阿保机次子。947年2月24日，辽太宗耶律德光将国号由“大契丹国”改为“大辽”，成为辽朝首位皇帝。");
            pEntries.Add("liao_taizu",
                "耶律阿保机出身契丹迭剌部，通过连续担任联盟首领和征服邻部，打破可汗定期轮替的旧制。他在九一六年称帝，建立契丹国，设置南北两套官制，并命人创制契丹大字，以适应草原部族与农耕州县并存的统治。阿保机东灭渤海、建立东丹国后在归途中去世，其制度与征服为后来辽朝的形成奠定基础。");
            pEntries.Add("liao_tianzhuo",
                "辽天祚帝耶律延禧（1075年6月5日—1128年），字延宁，小名阿果，辽顺宗耶律濬独子，是辽朝西迁前的最后一位皇帝，他的统治时间是从1101年2月12日至1125年3月26日，在位24年。天祚帝是辽道宗的孙子，他的父亲是道宗的太子耶律濬，母亲是贞顺皇后萧氏。六岁时他被封为梁王，九岁时封为燕国王。寿昌七年正月十三日（1101年2月12日），道宗崩，临死前立耶律延禧为继承人，耶律延禧奉遗诏即皇帝位于柩前。");
            pEntries.Add("liao_xingzong",
                "辽兴宗耶律宗真（1016年4月3日—1055年8月28日），契丹第七位皇帝（1031年6月25日—1055年8月28日在位），契丹名只骨。在位24年，享年40岁，谥孝章皇帝。他是辽圣宗的长子，母为元妃萧耨斤。");
            pEntries.Add("liu_chong",
                "汉世祖刘旻（895年—954年），原名刘彦崇、刘崇，并州晋阳（今山西太原）人，沙陀族，五代十国时期北汉开国皇帝，为后汉高祖刘知远弟，父为刘琠。刘崇年轻时喜欢饮酒赌博，曾经于脸上刺青从军。后唐长兴年间，迁魏州军校。刘知远于后晋任河东节度使时，他担任步军都指挥使。");
            pEntries.Add("liu_shouguang",
                "刘守光发动兵变夺取父亲刘仁恭控制的幽州，自任卢龙节度使，并以残酷手段清除异己。九一一年他不顾部属劝阻称帝，建立桀燕，随后与晋王李存勖争夺河北。晋军攻破幽州后刘守光与家人被俘，次年在太原被处死，燕政权由此覆亡。");
            pEntries.Add("liu_yan",
                "刘岩后来改名刘龑，是五代十国时期南汉政权的建立者，早年继承兄长刘隐在岭南的势力。九一七年他在广州称帝，先称大越，次年改国号为汉，并经营岭南及海上贸易。他晚年刑法严酷且宫廷奢侈，但其建国使南汉成为十国中延续数十年的南方政权。");
            pEntries.Add("ma_yin",
                "楚武穆王马殷（852年—930年12月2日），字霸图，许州鄢陵县（今河南鄢陵）人，五代十国时期南楚开国君王。马殷早年家贫，以木匠为业，后投入秦宗权军中，属孙儒部下，随孙儒渡淮攻下扬州。唐僖宗光启三年（887年），秦宗权派其弟秦宗衡为主将，孙儒为副将，将兵三万，南下渡过淮河，同杨行密争夺扬州。不久，孙儒杀秦宗衡，自立为帅，号“土团白条军”。");
            pEntries.Add("meng_zhixiang",
                "孟知祥受后唐庄宗任命为西川节度使，进入成都后逐步控制两川的财政、军队和官员任免。后唐明宗去世后，他摆脱中原政权约束并于九三四年称帝，建立后蜀。孟知祥即位不足一年便病逝，但其整合西川的基础使后蜀在孟昶统治下延续数十年。");
            pEntries.Add("nantang_liezu",
                "南唐烈祖李昪（bìan）（889年1月7日—943年3月30日），字正伦，小字彭奴，五代十国时期南唐开国皇帝，徐州人，原名徐知诰，是南吴权臣徐温养子，南唐第1任国主兼开国皇帝。李昪登基后便励精图治，使南唐的国力大为提升。关于李昪的身世，历史上众说纷纭，莫衷一是，宋朝司马光《资治通鉴考异》就收录了四种不同的说法。其中一种观点认为李昪是唐朝皇族后裔，持这种观点者以私修史着及杂史、稗史居多。");
            pEntries.Add("qian_liu",
                "吴越太祖钱镠（liú）（852年3月10日—932年5月6日），字具美（一作巨美），小名婆留，汉族，杭州临安县（今浙江省杭州市临安区）人。五代十国时期吴越国开国君主。唐末跟从石镜镇将军董昌镇压农民反抗军，任镇海节度使，乾宁年间击败董昌，占有两浙十三州，后梁开平元年被封为吴越王。在位期间，曾征用民工，修建钱塘江海塘，又在太湖流域，普造堰闸，以时蓄洪，不畏旱涝，并建立水网圩区的维修制度，有利于这一地区的农业经济。");
            pEntries.Add("song_bao_zheng",
                "包拯（999年3月5日—1062年7月3日），字希仁，庐州合肥（今安徽省合肥市肥东）人，北宋枢密副使，官至给事中，死后赠礼部尚书、谥「孝肃」。包拯以清廉公正闻名于世，被后世称誉为「包青天」，又被誉为「中国司法之神」。包拯曾任天章阁待制，人称「包待制」；后进为龙图阁直学士，故后人亦称「包龙图」。此外，其形象传说为黑面，故此亦被称为「包黑子」、「包黑炭」。");
            pEntries.Add("song_cao_bin",
                "曹彬（931年—999年），字国华，镇州灵寿县（今河北省灵寿县）人，北宋初名将，在北宋灭亡南唐的战争中担任主要将领，昭勋阁二十四功臣之一。后周显德三年（956年），改潼关监军，迁西上阁门使。显德五年（958年），奉诏出使吴越，奉诏赐吴越国王铠甲、弓弩、枪剑，及中吴军节度使钱文奉国信。显德六年（959年），判四方馆事，出为晋州兵马都监，转引进使；严于治军，尤重军纪。");
            pEntries.Add("song_cao_liyong",
                "曹利用（？—1029年），字用之。父曹谏，以明经得第，官至崇仪使。曹利用以父荫补殿前承旨，升迁为鄜延路走马承受公事。景德元年（1004年），契丹南侵，宋真宗御驾亲征，亲驻澶州（今河南省濮阳市），曹利用与契丹人订下澶渊之盟，以岁币三十万（每年白银10万两、绢帛20万匹）的价码缔结和约，获得真宗赏识。累官至枢密使、同中书门下平章事，加左仆射兼侍中。");
            pEntries.Add("song_chen_liang",
                "陈亮（1143年10月16日—1194年），原名汝能，字同甫，号龙川，学者称龙川先生，婺州永康县（今浙江永康市）人，南宋政治家、哲学家、词人。中又以上孝宗皇帝四书、《酌古论》最知名。日本西乡隆盛亦对龙川先生敬佩有加。");
            pEntries.Add("song_chen_yi",
                "陈与义是两宋之际诗人，靖康之变后辗转湖北、湖南和岭南，流离经历深刻改变其诗歌题材。他以《伤春》《登岳阳楼》等作品书写战乱、山河和个人身世，被视为江西诗派后期的重要作者。南宋建立后陈与义历任中书舍人、参知政事，兼有文学名声与中枢任职经历。");
            pEntries.Add("song_di_qing",
                "狄青（1008年—1057年5月3日），字汉臣，北宋河东路汾州西河（即今山西汾阳）人，出身寒门。北宋名将，打仗时常戴面具，曾讨伐西夏、广西侬智高，骁勇善战，立下赫赫战功，官至枢密使，谥武襄，追赠中书令、尚书令。于民间有着武曲星下凡之说，与「文曲星」包拯共同辅佐宋仁宗治国安民，是为宋朝一代传奇名臣。");
            pEntries.Add("song_duanzong",
                "宋端宗赵昰（shì）（1269年7月10日—1278年5月8日），南宋皇帝（1276年6月14日—1278年5月8日在位），在位2年，得年10虚岁，庙号端宗，谥号「裕文昭武愍孝皇帝」或「孝恭仁裕懿圣濬文英武勤政皇帝」，又有史称宋帝昰。他是宋度宗的五子，宋恭帝兄，曾被封为建国公、吉王、益王等。南宋德佑二年正月十八日（1276年2月4日）元军攻克临安时，宋恭帝和谢太皇太后相继被俘。时年7岁的赵昰和母亲杨淑妃和弟弟赵昺在国舅杨亮节等人护送下出逃至婺州，后又逃至温州。");
            pEntries.Add("song_duzong",
                "宋度宗赵禥（qí）（1240年5月2日—1274年8月12日），曾赐名赵孟启、赵孜，1253年立为皇子，赐名赵禥，是南宋皇帝（1264年11月16日－1274年8月12日在位），宋太祖的第十一世孙，宋理宗侄子。生父为荣王赵与芮，生母隆国夫人黄定喜。在位10年，享年34岁，死后葬于永绍陵，谥号「端文明武景孝皇帝」，是南宋灭亡前最后一位成年时即位的皇帝，也是整个宋朝最后一位握有实权的皇帝。度宗在位时期，战乱频仍，叛乱不断；朝廷被宰相贾似道把持，而度宗本人则沉迷于酒色，荒废政事。");
            pEntries.Add("song_fan_zhongyan",
                "范仲淹是北宋政治家、文学家，早年在地方任职时兴修海堤、整顿学校，并以直言进谏多次遭贬。他在西北主持对西夏防务，调整堡寨和训练制度；庆历年间又与富弼等推行新政，提出整顿吏治、选官和教育的方案。改革受阻后范仲淹继续治理地方，其《岳阳楼记》所写“先天下之忧而忧”成为后世评价其士大夫责任观的重要概括。");
            pEntries.Add("song_fu_bi",
                "富弼（1004年—1083年），字彦国，河南府（今河南洛阳东）人，北宋政治家、文学家。宋仁宗庆历二年（1042年）出使契丹，以增加岁币为条件，拒绝割地要求，即庆历增币；次年任枢密副使，与范仲淹等共同推行庆历新政，条上所拟河北守御十二策。庆历五年（1045年）被排挤，出知郓州、青州（今山东益都）。时河北大水，难民四处流亡。");
            pEntries.Add("song_gaozong",
                "宋高宗赵构（1107年6月12日—1187年11月9日），字德基，号损斋，南宋第一位皇帝，在位三十五年后禅让于宋孝宗。他是北宋皇帝宋徽宗第九子，宋钦宗之弟；曾获封为「康王」。金朝灭北宋后，俘虏包括徽宗与钦宗两任皇帝在内的皇族百余人。身为宋室仅存的希望，赵构南下逃亡，建立南宋，定都临安，是为宋高宗。");
            pEntries.Add("song_gongdi",
                "宋恭帝赵显（xiǎn）（1271年11月2日—1323年5月31日），南宋皇帝（1274年8月12日—1276年2月4日在位），在位2年，宋度宗六子。他是全皇后所生，是宋端宗赵昰之弟，宋末帝赵昺兄，即位前封嘉国公、左卫上将军等，也是宋朝的倒数第三位皇帝。1276年2月领宋室投降元朝后，封为瀛国公，而继位的宋端宗为他上尊号孝恭懿圣皇帝，无庙号与谥号。之后他被迫在吐蕃剃发出家，最后被赐死，享年53岁。");
            pEntries.Add("song_guangzong",
                "宋光宗赵惇（dūn）（1147年9月30日—1200年9月17日），南宋皇帝（1189年2月18日－1194年7月24日在位），宋孝宗第三子。42岁时受孝宗禅位而登基（亦是最老即位的宋帝），由于皇后李凤娘的挑拨，与父亲宋孝宗失和，赵汝愚、韩侂胄等大臣不满，宋孝宗死后，在太皇太后的支持下，光宗被迫内禅予其子宋宁宗，史称绍熙内禅。退位六年后驾崩，享年53岁，谥号「循道宪仁明功茂德温文顺武圣哲慈孝皇帝」。");
            pEntries.Add("song_han_derang",
                "韩德让（941年—1011年），字致尧，契丹名耶律隆运、兴宁·尧哥。出生于辽代世侯大族，祖籍河北玉田，辽朝大臣，政治家。韩德让的爷爷韩知古是被掳掠去辽国的汉人，后在辽国官至中书令。韩德让之父韩匡嗣是辽国的南京留守，卒于西南面招讨使任上，封秦王。");
            pEntries.Add("song_han_qi",
                "韩琦（1008年8月5日—1075年8月12日），字稚圭，自号赣叟，相州安阳人（今河南省安阳市），出生于泉州（今福建省泉州市鲤城区），北宋政治家，词人。他是天圣五年进士第二名，其后与范仲淹等主持庆历新政。仁宗嘉佑年间重返中央，先后担任枢密使、集贤相和昭文相。在担任首相的十年间，他辅弼三朝，也参与了英宗和神宗的册立，被誉爲“两朝定策元勳”。");
            pEntries.Add("song_han_shizhong",
                "韩世忠（1089年—1151年9月16日），字良臣，绥德军（今陕西省绥德县）人，南宋名将。官至太傅、镇南、武安、宁国军节度使、充醴泉观使、赐号扬武翊运功臣、封咸安郡王（从一品），太师致仕，赠通义郡王，追封蕲王、谥“忠武”。元配白氏死后，梁氏成为韩的正妻（野史称为梁红玉）。");
            pEntries.Add("song_han_tuozhou",
                "韩侂（tuō）胄（zhòu）（1152年11月6日—1207年11月24日），字节夫，籍贯河北路安阳（今河南），南宋中期的外戚、政治家、丞相、权臣，北宋名臣韩琦之曾孙，韩嘉彦孙，母亲为宋高宗吴皇后的妹妹。侂胄娶吴皇后的侄女为妻，无子。曾侄孙女是宋宁宗的恭淑皇后。侂胄曾与宋朝宗室赵汝愚合作，迫宋光宗禅位予其子嘉王赵扩，即宋宁宗，史称绍熙内禅，又任宁宗宰相，任内追封岳飞为鄂王，追夺秦桧官爵，力主北伐抗金，因将帅乏人而功亏一篑。");
            pEntries.Add("song_huang_tingjian",
                "黄庭坚（1045年—1105年），字鲁直，号山谷道人、豫章先生，晚号涪翁，洪州分宁（今江西九江市修水县）人，亦自称为南昌人。北宋诗人、书法家，江西诗派祖师。书法亦能树格，为宋四家之一。庭坚笃信佛教，亦慕道教，事亲颇孝，虽居官，却自为亲洗涤便器，亦为二十四孝之一。");
            pEntries.Add("song_huizong",
                "宋徽宗赵佶（Jí）（1082年11月2日—1135年6月4日），宋朝皇帝，1100年2月23日－1126年1月18日在位，自称教主道君皇帝，对瓷器、茶学、音律、金石学等领域有所研究，并擅长古琴、蹴鞠、击鞠、打猎、射箭、马术、绘画等，自创“瘦金书”字体。徽宗为宋神宗十一子，宋哲宗之弟，先后被封为遂宁郡王、端王。其兄长宋哲宗于1100年正月病逝时无子，向太后于同月立其为帝，并垂帘听政一年，第二年改年号为“建中靖国”。徽宗朝时期政治腐败，民不聊生，爆发宋江起义、方腊起义等多次民变。");
            pEntries.Add("song_jia_sidao",
                "贾似道（1213年8月25日—1275年10月9日），字师宪，号悦生、又号秋壑，台州（今浙江省台州市）人，为南宋丞相，在南宋灭亡前最后二十多年掌握朝廷大权。在《宋史》中被列入奸臣传。贾似道出生于宋宁宗嘉定六年（1213年），父贾涉，母胡氏，为涉之出妾。贾涉死时，贾似道年仅十一岁。");
            pEntries.Add("song_kou_zhun",
                "寇准（961年—1023年10月24日），字平仲，华州下邽（今陕西渭南）人，北宋大臣。与白居易、张仁愿并称「渭南三贤」。景德元年（1004年）拜相，任同平章事，时辽国侵宋，宋有迁都避难之议；但寇准力主宋真宗御驾亲征，后宋辽双方订立「澶渊之盟」，宋得以不亡。景德三年（1006年），被王钦若等排挤，失去相国之位。");
            pEntries.Add("song_li_chuyun",
                "李处耘（920年—966年），字正元，潞州上党（今山西长治）人，北宋开国将领，宋太宗第三任妻子皇后李氏的父亲。父亲李肇，后唐时官至检校司徒，力战契丹而死。李处耘生于五代后梁贞明六年（920年），生性勇武，以善射从军，与张彦泽相抗，“独当里门，射杀十数人，众无敢当者。”，后周显德二年（955年），折从阮病故前推荐李处耘。");
            pEntries.Add("song_li_gang",
                "李纲（1083年7月27日—1140年2月5日），字伯纪，祖籍福建邵武，父祖迁居无锡东乡胶山，故自号梁溪居士（梁溪为无锡古称）。宋徽宗政和二年（1112年）进士，与赵鼎、李光和胡铨合称“南宋四名臣”。李纲生于宋神宗元丰六年闰六月十日（1083年7月27日）秀州华亭官舍（今上海松江）。靖康元年（1126年）金兵侵汴京时，任京城四壁守御使，击退金兵。");
            pEntries.Add("song_li_hang",
                "李沆（947年—1004年），字太初，洺州肥乡人，北宋名臣。太平兴国五年，举进士甲科。真宗即位后，任户部侍郎、参知政事。秉性亮直，内行修谨，时称「圣相」。");
            pEntries.Add("song_liu_kezhuang",
                "刘克庄是南宋后期诗人、词人和官员，早年因《落梅》诗卷入诗禁，仕途多次起落。他关心边防与国势，作品常书写抗敌、用人和朝政得失，并参与国史院编修。刘克庄是江湖诗派的重要人物，著有《后村先生大全集》，其辛派词风保存了南宋末年的忧患意识。");
            pEntries.Add("song_liu_qi",
                "刘錡（1098年—1162年），字信叔。秦州成纪（今甘肃天水）人，宋朝名将，泸川军节度使刘仲武第九子，外表出众。通晓兵法与风水五行之术，擅长射箭，声音响亮如洪钟。宋孝宗追封为吴王，加太子太保。此卡侧重刘锜长期担任南宋前线将领、维持淮河防线和整训部队的军职身份。");
            pEntries.Add("song_liu_zhang",
                "刘錡（1098年—1162年），字信叔。秦州成纪（今甘肃天水）人，宋朝名将，泸川军节度使刘仲武第九子，外表出众。通晓兵法与风水五行之术，擅长射箭，声音响亮如洪钟。宋孝宗追封为吴王，加太子太保。此卡侧重刘锜在顺昌之战中依靠城防和士气以少胜多、击退金军的代表战功。");
            pEntries.Add("song_lizong",
                "宋理宗赵昀（1205年1月26日—1264年11月16日），原名赵与莒，后赐名赵贵诚，是南宋皇帝（1224年9月18日-1264年11月16日在位），宋太祖次子燕懿王赵德昭九世孙。宋理宗即位前原只是一位普通宗室，与皇位无缘，然时任皇帝宋宁宗之太子赵竑与权臣宰相史弥远不睦，1224年宁宗驾崩后，史弥远立赵贵诚为帝，是为宋理宗，即位后改名赵昀。宋理宗在位时间长达40年，是南宋在位时间最长的皇帝，享年59岁。");
            pEntries.Add("song_lu_you",
                "陆游（1125年11月13日—1210年1月26日），字务观，号放翁，越州山阴（今浙江绍兴）人，南宋诗人、词人。后人每以陆游为南宋诗人之冠。陆游自言“六十年间万首诗”，是中国历史上自作诗留存最多的诗人。陆游曾经请求废除凌迟，《凌迟刑》云：“肌肉已尽，而气息未绝，肝心联络，而视明尤存。");
            pEntries.Add("song_lv_huiqing",
                "吕惠卿（1032年9月25日—1111年），字吉甫，号恩祖。晋江人（今福建泉州），北宋大臣，曾任参知政事，是北宋新旧党争中的新党人物。着有《文集》《孝经传》《道德经注》《论语义》《庄子解》等作品。");
            pEntries.Add("song_meng_gong",
                "孟珙（1195年—1246年10月13日），字璞玉，自号无庵居士，随州枣阳（今湖北枣阳）人。早年随父亲孟宗政征战，崭露头角。宋金战争末期，率兵与蒙古军队联手围攻蔡州，灭亡金国，战后护送太常寺人马赴洛阳拜祭先帝陵墓。宋蒙战争初期，屡次率兵奔驰救援，守住重镇江陵，又在黄州开创宋蒙开战以来的空前大捷。");
            pEntries.Add("song_ningzong",
                "宋宁宗赵扩（1168年11月19日—1224年9月18日），南宋皇帝（1194年7月24日－1224年9月18日在位）在位30年，享年56岁，宋光宗之次子，李凤娘所生。宁宗本人颇为好学，即位初年召朱熹入宫讲学，受朱熹影响很深，但宁宗政治能力略显平庸。宁宗在位前期，太师韩侂胄打压理学，在韩侂胄死后，官方恢复了理学地位。纵观宋宁宗时期，大规模宋金战争发生了两次，第一次是开禧初年韩侂胄伐金，最终不能战胜金国，从而签订了嘉定和议。");
            pEntries.Add("song_ouyang_xiu",
                "欧阳修（1007年8月6日—1072年9月22日），名一作修，字永叔，号醉翁、晚号六一居士，籍贯吉州庐陵县（今江西省吉安市），生于绵州（今四川绵阳），北宋文学家、史学家、政治家，为“唐宋八大家”、“千古文章四大家”之一。他历仕仁宗、英宗、神宗三朝，官至翰林学士、枢密副使、参知政事，曾积极参与范仲淹所领导的庆历新政政治改革。文学方面，欧阳修成就斐然，是唐代韩愈、柳宗元所倡导之古文运动的继承者及推动者，为古文发展作出了巨大贡献。其散文风格平易自然，韵味深美，诗歌风格平易清新，为宋诗奠下基础，其辞赋创立文赋的新体裁，使中国辞赋有柳暗花明的新发展，所着两部史书《新唐书》及《新五代史》列入廿四部正史之中，所定家谱格式为后世历代沿用，经学上开创宋人直接解经、不依注疏的新风气，易学上打破易传的权威地位，在中国金石学、诗话及花谱撰作三方面，都是开山始祖。");
            pEntries.Add("song_pan_mei",
                "潘美（925年—991年），字仲询，大名府（今河北省邯郸市大名县）人，北宋初年名将。潘美与宋太祖赵匡胤素厚，宋朝建立后，受到重用，李重进叛乱，太祖亲征，命石守信为招讨使，美为行营都监以副之。扬州平，留为巡检，以任镇抚，以功授秦州团练使（阶官，从五品）。时湖南叛将汪端既平，人心未宁，乃授美潭州防御使（阶官，从五品）。");
            pEntries.Add("song_qian_weiyan",
                "钱惟演（977年—1034年），字希圣，钱塘（今浙江杭州）人，中国北宋诗人，本为吴越国末代国主钱俶之子，归顺宋朝后，成为西崑体领袖，其诗宗李商隐，见于《西崑集》。着有《典懿集》、《枢庭拥旄》前后集、《伊川汉上集》等，皆佚。政治上，为人趋炎附势，以裙带关系依附皇族，但亦好招徕名士，奖掖后进。追赠侍中，谥思，后改谥文僖。");
            pEntries.Add("song_qin_hui",
                "秦桧（huì）（1091年1月17日—1155年11月18日），字会之，江宁府（今江苏南京江宁）人，南宋初年的宠臣、书法家、诗人，官至太师，其生前的爵位封至建康郡王。宋徽宗政和五年（1115年）进士，补密州教授，北宋末年任御史中丞。靖康之祸后随同徽、钦二帝被掳到金国，宋高宗建炎四年（1130年）回到南宋。此后出任礼部尚书，两任宰相（仆射、同中书门下平章事兼枢密使），独揽相权十九年。");
            pEntries.Add("song_qinzong",
                "宋钦宗赵桓（huán）（1100年5月23日—1156年6月14日），宋朝皇帝（1126年1月19日－1127年3月20日在位）。宋徽宗赵佶长子，谥号「恭文顺德仁孝皇帝」。元符三年（1100年）四月十三日，生于坤宁殿。七月，赐名亶、授检校太尉、山南东道节度使、封韩国公，建中靖国元年（1101年）六月，迁兴德军节度使、开府仪同三司、进封京兆郡王。");
            pEntries.Add("song_renzong",
                "宋仁宗赵祯（1010年5月30日—1063年4月30日），宋朝皇帝（1022年3月23日－1063年4月30日在位）。初名受益，是宋真宗赵恒的第六子，也是唯一活到成年的皇子，生母李宸妃。天禧二年（1018年），进封昇王，同年九月立为皇太子，赐名祯。乾兴元年（1022年）二月，真宗崩，仁宗即帝位，时年13岁，由嫡母刘太后摄政；1023年改年号为天圣；1033年，刘太后归政，仁宗亲政；1063年驾崩于汴梁皇宫中，享年54岁，在位41年，为宋朝在位时间最长的皇帝。");
            pEntries.Add("song_shen_kuo",
                "沈括（1032年—1096年），字存中，晚年自号梦溪丈人、梦溪翁、岸老，本籍杭州钱塘县，自幼寄籍苏州吴县，北宋官员，官至龙图阁直学士、权三司使。沈括出身杭州官宦家庭，童年随父宦游，父亲死后荫补沭阳主簿。沈括任内成功治理沭水，然而始终不得提拔，于是参加科举连续考中苏州解元和进士，获任扬州司理参军，并在扬州得到日后丈人张蒭举荐入京任职馆阁，日后更为王安石提拔参与熙宁变法。在变法期间，沈括改革司天监、治理汴水、巡视两浙水利、视察河北西路边务并出使辽国，凭借诸多功绩受到宋神宗器重，一路拔擢至权三司使，总揽全国财政大权，但因政见不合受新党猜忌、排挤，宋神宗在蔡确力谏下不得不于熙宁十年（1077年）下诏罢免沈括，贬为宣州知州。");
            pEntries.Add("song_shenzong",
                "宋神宗赵顼（xū）（1048年5月25日—1085年4月1日），初名赵仲鍼，宋英宗的长子，是宋朝皇帝，1067年1月25日－1085年4月1日在位。在位期间主导熙宁变法和熙河开边，是北宋变法时代的主导者、开启者。庆历八年（1048年）四月十日，出生在濮安懿王宫邸睦亲宅，宋英宗赵曙和宣仁圣烈皇后高氏所生长子。八月，仁宗赐名为仲鍼，授太子右率府副率，迁太子右率府率。");
            pEntries.Add("song_shi_shouxin",
                "石守信（928年—984年7月11日）北宋初开国大将。石守信以“贪婪无厌”着称，史载：累任节度使，专务聚敛，积财钜万。尤信奉释教，在洛邑建崇德寺，募民工整瓦修木，驱迫甚急，而时常不给工钱，人多苦之。");
            pEntries.Add("song_sima_guang",
                "司马光（1019年11月17日—1086年10月11日），字君实，号迂叟，通称司马相公，陕州夏县涑水乡（今山西省夏县）人，出生于光州光山（今河南省信阳市光山县），北宋政治家、文学家、史学家。自称西晋安平献王司马孚的后裔。世称涑水先生，因身后追封温国公，又称司马温公。历仕仁宗、英宗、神宗、哲宗四朝，主持编纂了中国历史上第一部编年体通史《资治通鉴》。");
            pEntries.Add("song_su_shi",
                "苏轼（1037年1月8日—1101年8月24日），字子瞻，一字和仲，号东坡居士、铁冠道人，眉州眉山（今四川省眉山市）人，北宋文学家、政治家、艺术家。嘉佑二年进士，累官至端明殿学士兼翰林学士、礼部郎中、户部侍郎、兵部尚书。南宋理学方炽时，加赐谥号文忠，复追赠太师。有《东坡先生大全集》及《东坡乐府》词集传世，宋人王宗稷收其作品，编有《苏文忠公全集》。");
            pEntries.Add("song_taizong",
                "宋太宗赵炅（939年11月20日—997年5月8日），本名赵匡义（《宋史》作匡乂），其兄长赵匡胤登基后为避讳，受赐名赵光义，登基后为了避免社会上避讳过于扰民，自改名为罕用字「炅」。赵弘殷第三子，是北宋开国君主宋太祖赵匡胤的胞弟。宋朝皇帝（976年－997年在位），在位21年，享年57岁。赵匡胤去世后，赵光义继位，是为宋太宗，有「金匮之盟」为兄终弟及提供合法性依据。");
            pEntries.Add("song_taizu",
                "宋太祖赵匡胤（yìn）（927年3月21日—976年11月14日），字元朗，涿郡（今河北省保定市清苑区）人，中国宋朝（北宋）开国皇帝、政治家、军事家，父亲赵弘殷，母亲杜氏，自称西汉赵广汉之后。后唐明宗天成年间（927年3月21日）生于洛阳夹马营（今河南省洛阳市瀍河回族区东关）。后汉时，赵匡胤于后汉隐帝在位期间投奔郭威，之后郭威篡汉建立后周，是为周太祖。而赵匡胤则得任东西班行首，始入宦途。");
            pEntries.Add("song_wang_anshi",
                "王安石（1021年12月19日—1086年5月21日），字介甫，号半山，抚州临川县盐阜岭（今江西省抚州市临川区）人，北宋着名政治家、文学家、思想家、改革家，实官至司空、尚书左仆射、观文殿大学士、镇南军节度使，封荆国公。世人称之为“王荆公”、“王文公”。王安石文思敏捷，被后世称为唐宋八大家之一。除文学造诣外，王安石对传统经学也有研究，创立了在当时具有卓越影响力的学派——荆公新学，他的思想对宋明之季的经学学习产生了极大的影响，在当时也获得了很多关注。");
            pEntries.Add("song_wang_dan",
                "王旦（957年—1017年10月3日），因生于凌晨，取名旦，字子明，大名府莘县人，北宋政治人物。王旦其貌不扬，脸扁、鼻偏，喉部突起，有异人相。太平兴国五年（980年）进士及第（苏易简榜），时年二十三。旋以大理寺评事来到湖南平江任县令。");
            pEntries.Add("song_wang_qinruo",
                "王钦若（962年—1025年），字定国，临江军新喻（今江西省新余县东门王家）人，北宋初期的政治家。王钦若是真宗时期的宰相，属于当时的主和派，主张把国都南迁，与当时主战的寇准对立。他亦因为主导编纂《册府元龟》而知名。");
            pEntries.Add("song_wang_yucheng",
                "王禹偁（chēng）（954年—1001年），字元之，济州钜野（今山东菏泽市巨野县）人，北宋文学家。王禹偁出身清寒，家庭世代务农。从小发愤求学，五岁能写诗。宋太宗太平兴国八年（983年）中进士，最初担任成武县主簿。");
            pEntries.Add("song_wanyan_zongbi",
                "完颜宗弼（1090年代—1148年11月19日），女真名斡啜，一作兀术（zhú），又名乌珠，汉姓王，名宗弼（民间常称为金兀术（zhú））。女真皇室贵族，金太祖完颜阿骨打第四子，金国军事统帅。幼年时随金太祖完颜阿骨打起兵反辽。在反辽作战之中，完颜希尹获知辽天祚帝正在鸳鸯泺一带活动，于是宗望带领兀术分兵攻打，战斗中，兀术弓箭用尽，于是抢过辽国士兵的武器，杀了八名士兵，又生擒五人，通过审问获知天祚帝在鸳鸯泺打猎。");
            pEntries.Add("song_weizhu",
                "宋少帝赵昺（bǐng）（1272年2月12日—1279年3月19日），南宋皇帝，宋朝末代皇帝，在位313天（1278年5月10日－1279年3月19日在位），得年7岁。无正式庙号与谥号，后世史称祥兴帝、宋少帝、（宋）帝昺。宋朝第十五位皇帝宋度宗的七子，母俞修容，舅俞如珪。先后封为永国公、信王、广王等。");
            pEntries.Add("song_wen_tianxiang",
                "文天祥（1236年6月6日—1283年1月9日），初名云孙，字天祥，号浮休道人。选中贡士后，改天祥为名，字履善。宝佑年间考中状元，赐表字宋瑞，后因住过文山，而号文山，吉州庐陵富川（今江西吉安市吉安县）人。南宋末期政治家、诗人、抗元人物和民族英雄。");
            pEntries.Add("song_wen_tianxiang2",
                "陆秀夫（1238年11月15日—1279年3月19日），字君实，楚州盐城长建里（今江苏省盐城市建湖县）人，南宋末年政治家，与文天祥和张世杰并称为「宋末三杰」，于宋军在崖山之战失败时背着少帝跳海殉国，南宋灭亡。祖父陆大有，母赵氏乃宋朝宗室女。妻亦宋朝宗室女，两婆媳为姑侄。另有继室孟氏及妾倪氏与蔡氏。");
            pEntries.Add("song_wen_yanbo",
                "文彦博（1006年10月23日—1097年6月16日），字宽夫，号伊叟，河东路介休城关文家庄（今山西省介休市）人，北宋宰相。文彦博历仕仁、英、神、哲四朝，出将入相，长达五十年之久。任职期间，秉公执法，世人尊称为贤相。曾成功地抵御了西夏的入侵。");
            pEntries.Add("song_wu_jie",
                "吴玠（1093年—1139年7月18日），字晋卿，德顺军陇干（今甘肃静宁）人，后迁居水洛城（今甘肃庄浪），南宋初年抗金名将。父亲吴扆为军校，母亲刘氏，生二子吴玠、吴璘。少时沉毅有志节，知兵善骑射，读书能通大义。北宋宋徽宗宣和年间，参与平定方腊之乱和河北群盗，累功权泾原第十将。");
            pEntries.Add("song_xiaozong",
                "宋孝宗赵昚（shèn）（昚同慎；1127年11月27日—1194年6月28日），南宋皇帝（1162年7月24日－1189年2月18日在位），小名羊，原名伯琮，入宫时赐名瑗，过继宋高宗时更名玮，字元瑰，后又更名昚，更字元永，他是宋太祖第四子赵德芳的后裔，为宋高宗养子，宋太祖的嫡系子孙。宋孝宗登基，象徵自宋朝帝位落入宋太宗的子孙之手后，时隔186年终于恢复由开国皇帝宋太祖的后裔继承。孝宗是南宋较有作为的皇帝，同时期中原的皇帝是金朝的金世宗。");
            pEntries.Add("song_xie_fangshu",
                "谢枋得（1226年3月23日—1289年4月25日），字君直，号叠山，江南东路弋阳县（今江西）人，祖籍福建路邵武军，南宋遗民、文学家，隐居福建路建宁府建阳县、被元朝徵调至燕京，不降，绝食而死，门人私谥文节，世称谢文节公、文节先生。父谢应琇因忤据要津者，被董槐冤劾死，母亲桂氏深明大义，教养子孙。枋得自幼颖悟，“每观书，五行俱下，一览终身不忘”。宝佑四年（1256年）登文天祥榜进士二甲第一，除抚州司户参军，因董槐仍在位，拒不赴任。");
            pEntries.Add("song_xin_qiji",
                "辛弃疾（1140年5月28日—1207年10月3日），原字坦夫，后改爲幼安，号稼轩居士，山东东路济南府历城县（今山东省济南市历城区）人，南宋着名军事家、政治家及文学家。其出生时家乡已沦陷于金国统治，少年时即已参与抗金游击队，其后率部投奔南宋并曾任江西安抚使、福建安抚使等职，但因归正人身份，终生未能得到宋廷重用并无法实现北伐夙愿，仅于身后获追赠少师、谥忠敏。辛弃疾同时亦是豪放派词人，被誉为词中之龙，与苏轼合称「苏辛」、与李清照（字易安）并称「济南二安」。");
            pEntries.Add("song_yan_shu",
                "晏殊（991年—1055年2月27日），字同叔，江西抚州临川县文港乡（今南昌市进贤县文港镇）人，北宋前期政治家、婉约派词人，与欧阳修并称「晏欧」。他本人又被称为“太平宰相”。晏殊是词人晏几道父亲，世称晏殊为大晏，晏几道为小晏。");
            pEntries.Add("song_yang_yanzhao",
                "杨延昭（958年—1014年），并州太原（今山西太原）人，本名延朗，北宋抗辽名将。在边防二十余年，契丹畏之，目为“杨六郎”。官至莫州防御使、高阳关马步军副都部署，与其父杨业、子杨文广三代并称名将，号为“杨家将”。");
            pEntries.Add("song_yang_ye",
                "杨业（923年—986年），又名继业，最初名为重贵，河东路并州太原（今山西省太原市）阳曲人，北宋抗辽将领。曾经担任云州观察使，在雍熙北伐中被俘，最终绝食殉国，朝廷追赠检校太尉、大同军节度使；杨业与其子杨延昭、孙杨文广三代忠烈为国，刚正不阿，并称“杨家将”。杨业本名杨重贵，并州太原（今山西太原）人。年少时便擅长骑射，立志成为名将。");
            pEntries.Add("song_yang_yi",
                "杨亿（974年—1020年），字大年，人称杨文公。建州浦城（今属福建浦城县）人。自幼是个神童，博览强记，太宗雍熙元年（984年），十一岁受宋太宗召试，授秘书省正字（掌管图书秘籍的次长），淳化三年（992年）进士及第，迁光禄寺丞。至道二年（996年）迁着作佐郎。");
            pEntries.Add("song_yao_lin",
                "姚麟（1038年—1105年），字君瑞。因父荫入仕，在熙河之役率先攻下河州（今甘肃），深受王韶赏识。随大哥姚兕攻打河州，他和哥哥俱在军中。中箭穿透骨头，箭头留在骨内拔不出，用强弓拔出来，谈笑自若。");
            pEntries.Add("song_ye_shi",
                "叶适是南宋永嘉学派代表人物，反对脱离现实的空疏义理，强调财政、兵制和地方治理的实际功效。他曾参与朝政并为抗金与江防提出建议，韩侂胄北伐失败后又参与处理善后。其《水心文集》《习学记言序目》系统表达经世主张，对南宋事功之学影响深远。");
            pEntries.Add("song_yelu_xiuge",
                "耶律休哥（？—998年），字逊宁。祖父为隋王耶律释鲁，父为南院夷离菫耶律绾思。官至辽国的于越，封宋国王。东丹王耶律倍、耶律德光族兄弟，世宗、穆宗族叔，景宗叔祖，圣宗同族曾祖。");
            pEntries.Add("song_yingzong",
                "宋英宗赵曙（1032年2月16日—1067年1月25日），原名赵宗实，是宋太宗曾孙，濮王赵允让之子，过继给宋仁宗为嗣，是宋朝皇帝，1063年5月1日－1067年1月25日在位。赵曙是前任第四代皇帝仁宗的堂兄濮王赵允让的第十三子，是太宗第四子商王赵元份的后裔，生母为仙游县君任氏。天圣十年（明道元年）壬申年正月三日甲戌（1032年2月15日）生于宣平坊宅第〔嘉佑八年（1063年），英宗把这天定为“寿圣节”〕，最初，濮王梦两龙与太阳一起掉落下来，用衣服装住了它们，到英宗出生时，赤光满室，有黄龙在赤光中游走。");
            pEntries.Add("song_yu_yunwen",
                "虞允文（1110年—1174年），字彬甫，世称虞雍国、虞雍公，隆州仁寿（今四川仁寿县）人，宋朝宰相和军事家。虞允文，字彬甫，世称虞雍国、虞雍公，隆州仁寿（今四川仁寿县）人，宋朝宰相和军事家。虞允文生于北宋徽宗大观四年（1110年）。自幼勤奋好学，《宋史》称其「六岁诵九经，七岁能属文」，读书于瑞竹园（仁寿县城东面）。");
            pEntries.Add("song_yue_fei",
                "岳飞（1103年3月24日—1142年1月27日），字鹏举，宋朝相州汤阴（今河南省安阳市汤阴县）人。南宋抗金名将及民族英雄，官至少保、枢密副使，受封武昌郡开国公。遭大臣秦桧等人诬陷而被宋高宗赐死。多年后，宋孝宗为其平反，追谥武穆。");
            pEntries.Add("song_zeng_gong",
                "曾巩（1019年9月30日—1083年4月30日），字子固，建昌南丰（今江西南丰）人，北宋散文家，被誉为“唐宋八大家”之一。曾巩，字子固，建昌南丰（今江西南丰）人，北宋散文家，被誉为“唐宋八大家”之一。宋天禧三年（1019年），八月二十五生于江西南丰一个官宦人家，十二岁作《六论》一篇，为当时所推祟。十八岁随父曾易占迁移至玉山县（在江西境内），周游当地，写成了《游信州玉山小岩记》，内容主要是记述玉山县的地貌，包括溶洞、岩石等等。");
            pEntries.Add("song_zhang_dun",
                "章惇（1035年12月29日—1106年1月2日），字子厚，建州浦城县（今福建省蒲城县）人，宋朝政治人物，新旧党争的变法派要角。《挥麈录》称章惇是父亲章俞与其丈母娘杨氏通奸所生的奸生子，假冒为章俞之妻罗氏所生。宋仁宗嘉佑二年（1057年）考取进士，可是族侄章衡考取状元，便不就而去。嘉佑四年再举进士甲科，调知商洛县、雄武军节度推官，改着作佐郎，知常州武进县。");
            pEntries.Add("song_zhang_jun",
                "张浚在靖康之变后拥护宋高宗南渡，长期主持川陕和长江上游的抗金军政。他组织富平之战虽遭失败，仍持续整合吴玠等部防守西线，并多次主张北伐恢复中原。隆兴北伐失利后张浚再次离开中枢，其一生体现南宋主战路线的坚持与军事动员困境。");
            pEntries.Add("song_zhang_xian",
                "张宪是岳飞麾下的重要将领，长期参加岳家军对金作战并承担前锋、守城和部队统率任务。他参与收复襄阳六郡及郾城前后的战事，是岳飞北伐体系中的骨干。绍兴和议前后张宪与岳飞、岳云一同遭到诬陷和处死，其结局成为南宋军事集团受政治清算的代表事件。");
            pEntries.Add("song_zhao_pu",
                "赵普（922年—992年8月14日），字则平。在陈桥兵变中立功，协助赵匡胤登上帝位，为宋开国功臣。后参与解除禁军将领兵权的谋划，并提出了“稍夺其权，制其钱谷，收其精兵”的纲领，解决了长期以来的藩镇动乱问题，巩固中央集权。赵普与赵光义曾有龃龉，但在赵光义即位后，赵普帮助赵光义稳定皇位，两次拜相。");
            pEntries.Add("song_zhenzong",
                "宋真宗赵恒（968年12月23日—1022年3月23日），原名赵德昌，曾用名赵元休、赵元侃，宋朝皇帝。他是宋太宗的第三个儿子，登基前曾被封为韩王、襄王和寿王，淳化五年（994年）九月，加检校太傅行开封府尹，至道三年（997年）四月登基后离任，以太子身份继位，在位25年。宋真宗赵恒，原名赵德昌，曾用名赵元休、赵元侃，宋朝皇帝。乾德六年十二月初二日（968年12月23日），生于东京开封府第，生母李氏是父亲赵光义的妾室之一。");
            pEntries.Add("song_zhezong",
                "宋哲宗赵煦（1077年1月4日—1100年2月23日），宋朝皇帝（1085年4月1日－1100年2月23日在位），为宋神宗第六子，母亲为钦成皇后朱氏。生于熙宁九年十二月七日（1077年1月4日），神宗病危时立他为太子。元丰八年，神宗驾崩，赵煦登基为皇帝，是为宋哲宗，改元“元佑”。在位15年，得年二十三岁，葬于今天河南巩义市的永泰陵。");
            pEntries.Add("song_zong_ze",
                "宗泽（1060年1月20日—1128年7月29日），字汝霖，婺州义乌人，中国宋朝名臣，南宋高宗时任东京留守兼知开封府，重用岳飞北伐，并多次请高宗迁回开封府未果，为权臣所抑，积愤成疾，疽发与背而死。宗泽出生于嘉佑四年十二月乙亥（十四）日（1060年1月20日）。早年家贫，元佑六年（1091年）马绢榜进士及第，召廷对，直陈时弊，主文者恶其直，置末甲。八年（1093年），以将仕郎调馆陶县尉。");
            pEntries.Add("wang_jian",
                "前蜀高祖王建（847年2月26日—918年7月11日），字光图，五代十国时期前蜀开国皇帝（907年－918年在位），许州舞阳县（今河南舞阳）人。少年时为无赖，以屠牛驴和贩私盐为业，乡里称为“贼王八”，黄巢起事时期投效唐朝军队，隶属忠武军。长安沦陷时他奋不顾身地护驾，号为“随驾五都”，为忠武八都的都将之一，被唐僖宗封为西川节度使、壁州刺史，十军观军容使田令孜也收他为养子。僖宗还长安后，升为御林军宿卫将领。");
            pEntries.Add("wang_shenzhi",
                "闽太祖王审知（862年10月5日—925年12月30日），字信通，一字详卿，是五代十国时期闽国开国君主，909年至925年在位。咸通三年九月八日（862年10月5日），王审知诞辰于淮南道光州固始县（今河南省信阳市固始县），为王恁第三子，也是王潮和王审邽之弟。出身贫苦，后在唐末民变期间，与两位兄长一起加入王绪的军队，随之转战福建。其兄王潮被唐昭宗任命为福建观察使后，他也获封观察副使，后福建观察使升格为威武军节度使，898年，继承兄位。");
            pEntries.Add("xi_xia_chongzong",
                "李乾顺三岁即位为西夏崇宗，前期朝政由梁太后及外戚控制，西夏继续与宋、辽交战。他成年后借助辽朝力量诛除梁氏，收回君权，并整顿官制、学校和法律。辽宋相继衰落后，他在金、宋之间调整外交，使西夏获得较长和平并恢复国力。");
            pEntries.Add("xi_xia_huanzong",
                "夏桓宗李纯佑（1177年—1206年3月），夏仁宗子。1193年10月16日，夏仁宗李仁孝去世，李纯佑即位，时年十七，改元天庆。桓宗基本上还能奉行仁宗时期的政治方针和外交政策，对内安国养民，对外附金和宋。但随着国家的安定承平日久，统治阶层开始贪图安逸，日益腐朽堕落，从此西夏政治日益腐败，国势衰落。");
            pEntries.Add("xi_xia_huizong",
                "夏惠宗李秉常（1061年—1086年8月21日），西夏第三位皇帝（1068年1月27日－1086年8月21日在位）。拱化五年农历十二月（1068年1月），毅宗突然病死，英年早逝，年二十一，惠宗以七岁稚龄继位，生母梁太后及其家族专权，执政期间没有任何治国良策，西夏国势积弱，北宋乘机入侵。十六岁时本能亲政，但梁氏势力很大，不能轻易翦灭，因此他仍然不能亲政。后来因长期不能亲政，忧愤而死，天安礼定二年（1086年）农历七月十日去世，享年仅二十六岁，谥号康靖皇帝。");
            pEntries.Add("xi_xia_jingzong",
                "李元昊（1003年6月7日—1048年1月19日），党项名嵬名曩霄，即夏景宗，是西夏的建立者及首位皇帝，1032年至1048年统治党项政权，1038年至1048年在皇帝位。其祖父为夏太祖李继迁，父亲为夏太宗李德明。元昊早年随父出兵河西，攻取甘州后被立为太子；李德明去世后继承夏州政权，逐步改易姓氏、服饰、文字、礼仪与官制，并于1038年建国称帝。元昊称帝后，宋廷拒绝承认其帝号，双方遂爆发数年战争。");
            pEntries.Add("xi_xia_modi",
                "李睍（xiàn）（？—1227年8月28日），夏献宗侄，父清平郡王，夏献宗病危时被推举为帝，史称「末帝」，又称失都儿忽。李睍在位时已为西夏灭亡的前夕，曾拒降蒙古。右丞相高良惠及各将士积极抵抗蒙古，但无奈天意造化弄人，中兴府发生大地震，以致瘟疫肆虐，粮水短缺，军民死伤过半，使西夏注定灭亡。");
            pEntries.Add("xi_xia_renzong",
                "夏仁宗李仁孝（1124年—1193年10月16日），夏崇宗次子，母为汉人曹贵妃。仁宗皇帝为清圣祖以前在位最长的中国皇帝，是中国历史上在位第三长的皇帝。由于其兄李仁爱先于崇宗而死，故被立为太子。1139年7月1日夏崇宗李乾顺去世，李仁孝即位，时年十六岁。");
            pEntries.Add("xi_xia_shenzong",
                "夏神宗李遵顼（1163年—1226年），西夏宗室齐国忠武王李彦宗之子。史书记载：「端重明粹，少力学，长博通群书，工隶篆」。1203年，廷试进士第一名，1211年8月12日，李遵顼发动政变，废黜襄宗李安全，李遵顼即位，是为夏神宗。改元光定，成为中国历史上唯一的状元皇帝。");
            pEntries.Add("xi_xia_xiangzong",
                "夏襄宗李安全（1170年—1211年9月13日），西夏皇帝。夏崇宗孙，其父乃夏仁宗弟越王李仁友，1196年，仁友逝，安全上书要求袭越王爵位，桓宗不许，安全被降封为镇夷郡王，他极为不满，于是萌生了篡夺皇位之心。1206年3月1日与桓宗母罗氏合谋，废桓宗自立，改元应天。在位时昏庸无能，破坏金国与西夏长期的友好关系，发兵侵金，为后来一场场令夏金耗尽精兵的战役掀起序幕，改附不断强大起来的蒙古帝国，但这一切都没有为西夏带来利益和跟蒙古之友好，蒙古也以西夏作为侵略目标，西夏不断积弱。");
            pEntries.Add("xi_xia_xianzong",
                "夏献宗李德旺（1181年—1226年），夏神宗之次子。力挽面临灭亡的西夏，但西夏经过襄宗、神宗两朝的亡国政策，人民早已生活于水深火热之困境中，经济疲弊，他根本没有回天之力。他一改前朝政策，决心与金国修好，于1225年正式和好；然金都也被蒙古包围，金国已是自身难保。又改国策附蒙为抗蒙，但西夏精兵早于夏金战役中消耗殆尽，无力抵抗蒙古军，终于1226年惊忧而死，年46岁，庙号献宗。");
            pEntries.Add("xi_xia_yizong",
                "夏毅宗李谅祚（1047年3月5日—1068年1月），西夏第二位皇帝（1048年—1068年1月在位）。夏景宗之子，生母没藏氏，党项族人。天授礼法延祚十年（1047年）农历二月六日，没藏氏在跟从李元昊贺兰山打猎时生下李谅祚。");
            pEntries.Add("yang_xingmi",
                "杨行密（852年－905年11月庚辰，一说906年二月），原名行愍，字化源，庐州合肥人，唐末军阀、政治人物，杨吴政权奠基者。杨行密起兵于庐州，乘唐末淮南大乱而崛起，先后夺取宣州、扬州，击灭孙儒，进而控制江淮地区。景福元年（892年），唐廷授杨行密淮南节度使；乾宁二年（895年），加同中书门下平章事，封弘农郡王；天复二年（902年），进封吴王。杨行密据有江淮后，实行保境安民、招合流散、减轻赋敛、劝课农桑等政策，使江淮在晚唐战乱中较早恢复，亦为其后杨吴、南唐的政治与经济发展奠定基础。");
            pEntries.Add("yuan_dingzong",
                "元定宗贵由，姓孛儿只斤氏，讳贵由，又译古余克。大蒙古国皇帝，1246年—1248年在位。元太宗窝阔台长子，母昭慈皇后脱列哥那。元太宗五年（1233年），奉旨率左翼军，与按赤台攻辽东，擒蒲鲜万奴。");
            pEntries.Add("yuan_shizu",
                "元世祖忽必烈，清代乾隆帝时命改译为呼必赉，孛儿只斤氏，蒙古黄金家族成员。他是成吉思汗之孙，拖雷的第四子，母亲唆鲁禾帖尼的第二子，蒙哥的弟弟。忽必烈是中国历史上元朝的建立者及其最享负盛名的君主，其于1260年5月在汉臣拥戴下登基为大蒙古国皇帝，1271年12月更改国号为大元、成为首任元朝皇帝，1279年3月起统治全中国，前后在位34年，作为全中国皇帝在位近15年。忽必烈雄才大略，早年获派管理金朝故土，开始受汉文化影响，因此很早便招揽各种汉人人才，慢慢形成自己的幕僚班子「金莲川幕府」，为后来的统治奠下基础，并多次随从蒙哥南征大理、南宋。");
            pEntries.Add("yuan_taizong",
                "窝阔台汗，又作斡歌歹、和歌台、倭阔岱等，孛儿只斤氏，成吉思汗第三子，大蒙古国大汗。他是蒙古帝国第二位大汗，1229年9月13日－1241年12月11日在位，在位12年零3个月。他登基时接受大汗的称号，和诸汗相区别。至元三年（1266年）十月，太庙成，元廷追尊庙号太宗，谥英文皇帝。");
            pEntries.Add("yuan_taizu",
                "成吉思汗（约1162年—1227年8月25日），本名铁木真，是大蒙古国的创建者，被后世元朝追尊为元太祖。成吉思汗一生大多时光都用于统合蒙古族诸部落，继而发起连番军事征伐，征服中国及中亚的大片疆土。成吉思汗是蒙古孛儿只斤氏首领也速该和妻子诃额仑的长子，生于1155年至1167年间，因铁木真兀格而取名「铁木真」。铁木真八岁时，父亲亡故，他的家庭遭部落抛弃。");
            pEntries.Add("yuan_xianzong",
                "蒙哥汗，蒙古汗国第四任大汗，也是蒙古帝国分裂前最后一个受到普遍承认以及能够直接管治整个帝国的大汗，蒙古帝国在蒙哥汗时面积约为2400万平方公里。他是成吉思汗幼子拖雷的长子、窝阔台的养子，由窝阔台的昂灰皇后抚养长大。1251年7月1日登基，在位8年零2个月。期间长期主持对南宋、大理的战争，为其弟忽必烈最终建立元朝奠定坚实基础。");
        }
    }
}
